135deg,rgb(2,3,129) 0%,rgb(40,116,252) 100%);--wp--preset--duotone--dark-grayscale: url('#wp-duotone-dark-grayscale');--wp--preset--duotone--grayscale: url('#wp-duotone-grayscale');--wp--preset--duotone--purple-yellow: url('#wp-duotone-purple-yellow');--wp--preset--duotone--blue-red: url('#wp-duotone-blue-red');--wp--preset--duotone--midnight: url('#wp-duotone-midnight');--wp--preset--duotone--magenta-yellow: url('#wp-duotone-magenta-yellow');--wp--preset--duotone--purple-green: url('#wp-duotone-purple-green');--wp--preset--duotone--blue-orange: url('#wp-duotone-blue-orange');--wp--preset--font-size--small: 13px;--wp--preset--font-size--medium: 20px;--wp--preset--font-size--large: 36px;--wp--preset--font-size--x-large: 42px;}.has-black-color{color: var(--wp--preset--color--black) !important;}.has-cyan-bluish-gray-color{color: var(--wp--preset--color--cyan-bluish-gray) !important;}.has-white-color{color: var(--wp--preset--color--white) !important;}.has-pale-pink-color{color: var(--wp--preset--color--pale-pink) !important;}.has-vivid-red-color{color: var(--wp--preset--color--vivid-red) !important;}.has-luminous-vivid-orange-color{color: var(--wp--preset--color--luminous-vivid-orange) !important;}.has-luminous-vivid-amber-color{color: var(--wp--preset--color--luminous-vivid-amber) !important;}.has-light-green-cyan-color{color: var(--wp--preset--color--light-green-cyan) !important;}.has-vivid-green-cyan-color{color: var(--wp--preset--color--vivid-green-cyan) !important;}.has-pale-cyan-blue-color{color: var(--wp--preset--color--pale-cyan-blue) !important;}.has-vivid-cyan-blue-color{color: var(--wp--preset--color--vivid-cyan-blue) !important;}.has-vivid-purple-color{color: var(--wp--preset--color--vivid-purple) !important;}.has-black-background-color{background-color: var(--wp--preset--color--black) !important;}.has-cyan-bluish-gray-background-color{background-color: var(--wp--preset--color--cyan-bluish-gray) !important;}.has-white-background-color{background-color: var(--wp--preset--color--white) !important;}.has-pale-pink-background-color{background-color: var(--wp--preset--color--pale-pink) !important;}.has-vivid-red-background-color{background-color: var(--wp--preset--color--vivid-red) !important;}.has-luminous-vivid-orange-background-color{background-color: var(--wp--preset--color--luminous-vivid-orange) !important;}.has-luminous-vivid-amber-background-color{background-color: var(--wp--preset--color--luminous-vivid-amber) !important;}.has-light-green-cyan-background-color{background-color: var(--wp--preset--color--light-green-cyan) !important;}.has-vivid-green-cyan-background-color{background-color: var(--wp--preset--color--vivid-green-cyan) !important;}.has-pale-cyan-blue-background-color{background-color: var(--wp--preset--color--pale-cyan-blue) !important;}.has-vivid-cyan-blue-background-color{background-color: var(--wp--preset--color--vivid-cyan-blue) !important;}.has-vivid-purple-background-color{background-color: var(--wp--preset--color--vivid-purple) !important;}.has-black-border-color{border-color: var(--wp--preset--color--black) !important;}.has-cyan-bluish-gray-border-color{border-color: var(--wp--preset--color--cyan-bluish-gray) !important;}.has-white-border-color{border-color: var(--wp--preset--color--white) !important;}.has-pale-pink-border-color{border-color: var(--wp--preset--color--pale-pink) !important;}.has-vivid-red-border-color{border-color: var(--wp--preset--color--vivid-red) !important;}.has-luminous-vivid-orange-border-color{border-color: var(--wp--preset--color--luminous-vivid-orange) !important;}.has-luminous-vivid-amber-border-color{border-color: var(--wp--preset--color--luminous-vivid-amber) !important;}.has-light-green-cyan-border-color{border-color: var(--wp--preset--color--light-green-cyan) !important;}.has-vivid-green-cyan-border-color{border-color: var(--wp--preset--color--vivid-green-cyan) !important;}.has-pale-cyan-blue-border-color{border-color: var(--wp--preset--color--pale-cyan-blue) !important;}.has-vivid-cyan-blue-border-color{border-color: var(--wp--preset--color--vivid-cyan-blue) !important;}.has-vivid-purple-border-color{border-color: var(--wp--preset--color--vivid-purple) !important;}.has-vivid-cyan-blue-to-vivid-purple-gradient-background{background: var(--wp--preset--gradient--vivid-cyan-blue-to-vivid-purple) !important;}.has-light-green-cyan-to-vivid-green-cyan-gradient-background{background: var(--wp--preset--gradient--light-green-cyan-to-vivid-green-cyan) !important;}.has-luminous-vivid-amber-to-luminous-vivid-orange-gradient-background{background: var(--wp--preset--gradient--luminous-vivid-amber-to-luminous-vivid-orange) !important;}.has-luminous-vivid-orange-to-vivid-red-gradient-background{background: var(--wp--preset--gradient--luminous-vivid-orange-to-vivid-red) !important;}.has-very-light-gray-to-cyan-bluish-gray-gradient-background{background: var(--wp--preset--gradient--very-light-gray-to-cyan-bluish-gray) !important;}.has-cool-to-warm-spectrum-gradient-background{background: var(--wp--preset--gradient--cool-to-warm-spectrum) !important;}.has-blush-light-purple-gradient-background{background: var(--wp--preset--gradient--blush-light-purple) !important;}.has-blush-bordeaux-gradient-background{background: var(--wp--preset--gradient--blush-bordeaux) !important;}.has-luminous-dusk-gradient-background{background: var(--wp--preset--gradient--luminous-dusk) !important;}.has-pale-ocean-gradient-background{background: var(--wp--preset--gradient--pale-ocean) !important;}.has-electric-grass-gradient-background{background: var(--wp--preset--gradient--electric-grass) !important;}.has-midnight-gradient-background{background: var(--wp--preset--gradient--midnight) !important;}.has-small-font-size{font-size: var(--wp--preset--font-size--small) !important;}.has-medium-font-size{font-size: var(--wp--preset--font-size--medium) !important;}.has-large-font-size{font-size: var(--wp--preset--font-size--large) !important;}.has-x-large-font-size{font-size: var(--wp--preset--font-size--x-large) !important;}
.wp-block-image.aligncenter {
    display: block !important;
}

.is-style-bb>.c-tabList .c-tabList__button:hover,
.is-style-bb>.c-tabList .c-tabList__button[aria-selected=true] {
    color: #fff !important;
}

/* =========================================================
   比較テーブル（.pcx）デザインリニューアル版
   テーマ：落ち着いたクリニック調
   ボルドー（#8E292C）× ローズブラウン × シャンパンゴールド ／ CVはアンバー
   ※サイズ・レイアウト・JS連動クラス（pcx-js / is-scrolled / is-start / is-end /
     hint-done / on / flash / colfocus など）は既存仕様のまま。色・装飾のみ変更。
   ========================================================= */
.pcx{--ink:#8E292C;--ink2:#6E1E21;--steel:#5e4344;--teal:#9a4a40;--teal-l:#f8eeeb;--teal-b:#ebcdc6;--gold:#b48f57;--gold2:#ecd7ae;--gold-dk:#8a6a3a;--cream:#fdf9f2;--cream2:#f7efe0;--sand:#f8f3ee;--red:#b3262b;--cv1:#f39a4a;--cv2:#e0712b;--cv3:#b4521a;--line:#ebe1d8;--zebra:#fbf8f5;--text:#2e2222;--muted:#7d7272;--off:#aba3a0;--c1:#b48f57;--c2:#8E292C;--c3:#9a7b6a;margin:1.6em 0;font-family:"Hiragino Kaku Gothic ProN","Hiragino Sans","Noto Sans JP",sans-serif;color:var(--text);}
.pcx *{box-sizing:border-box;}
.pcx,.pcx *{word-break:normal!important;overflow-wrap:normal!important;hyphens:none!important;}

/* ===== タイトル ===== */
.pcx .pcx-head{position:relative;display:flex;align-items:flex-end;justify-content:space-between;gap:8px;margin:0 2px 8px;padding:0 0 6px;border-bottom:1px solid var(--line);}
.pcx .pcx-head::after{content:"";position:absolute;left:0;bottom:-1px;width:48px;height:2px;background:var(--gold);}
.pcx .pcx-ttl{margin:0!important;padding:0!important;background:none!important;border:none!important;font-size:13.5px;font-weight:800;color:var(--ink);line-height:1.35;letter-spacing:.04em;}
.pcx .pcx-ttl small{display:block;font-family:"Helvetica Neue",Arial,sans-serif;font-size:9.5px;font-weight:600;color:var(--gold);letter-spacing:.3em;margin-bottom:2px;}
.pcx .pcx-hint{flex:none;display:flex;align-items:center;gap:4px;margin:0!important;padding:3px 9px!important;border-radius:999px;background:var(--teal-l);color:var(--teal);border:1px solid var(--teal-b);font-size:9.5px;font-weight:700;line-height:1.3;transition:opacity .3s;}
.pcx .pcx-hint svg{width:13px;height:13px;fill:none;stroke:var(--teal);stroke-width:2.4;stroke-linecap:round;stroke-linejoin:round;animation:pcx-swipe 1.4s ease-in-out infinite;}
.pcx.is-scrolled .pcx-hint{opacity:0;}
@keyframes pcx-swipe{0%,100%{transform:translateX(0)}50%{transform:translateX(4px)}}

/* ===== テーブル上部（タイトル・横スクロール表示・項目ジャンプ）は非表示 ===== */
.pcx .pcx-head,.pcx .pcx-nav,.pcx.pcx-js .pcx-nav{display:none!important;}

/* ===== 項目ジャンプ（JS有効時のみ表示） ===== */
.pcx .pcx-nav{display:none;gap:4px;margin:0 0 6px;padding:0 0 2px;overflow-x:auto;scrollbar-width:none;}
.pcx .pcx-nav::-webkit-scrollbar{display:none;}
.pcx.pcx-js .pcx-nav{display:flex;}
.pcx .pcx-nav button{flex:none;appearance:none;-webkit-appearance:none;margin:0;padding:5px 9px;border-radius:999px;border:1px solid var(--line);background:#fff;color:var(--ink);font:inherit;font-size:10px;font-weight:700;line-height:1.2;cursor:pointer;white-space:nowrap;transition:.15s;}
.pcx .pcx-nav button:hover{border-color:var(--teal);color:var(--teal);}
.pcx .pcx-nav button.on{background:var(--ink);border-color:var(--ink);color:#fff;box-shadow:inset 0 -2px 0 var(--gold);}
.pcx .pcx-nav button[data-go="cv"]{border-color:var(--cv1);color:var(--cv3);}
.pcx .pcx-nav button[data-go="cv"].on{background:var(--cv2);border-color:var(--cv2);color:#fff;box-shadow:none;}
.pcx .pcx-nav .nav-lbl{flex:none;align-self:center;font-size:9px;font-weight:700;color:var(--muted);letter-spacing:.06em;margin-right:2px;}

/* ===== スクロール枠 ===== */
.pcx .pcx-wrap{position:relative;}
.pcx .pcx-scroll{overflow-x:auto!important;overflow-y:hidden;border:1px solid var(--line);border-radius:14px;background:#fff;box-shadow:0 1px 2px rgba(110,30,33,.05),0 10px 26px -10px rgba(110,30,33,.22);}
.pcx .pcx-fade{position:absolute;top:1px;right:1px;bottom:1px;width:26px;border-radius:0 13px 13px 0;background:linear-gradient(to right,rgba(255,255,255,0),rgba(110,30,33,.12));pointer-events:none;transition:opacity .3s;}
.pcx.is-end .pcx-fade{opacity:0;}
.pcx .pcx-bar{display:none;height:4px;margin:5px 30% 0;border-radius:3px;background:#ece7de;overflow:hidden;}
.pcx.pcx-js .pcx-bar{display:block;}
.pcx .pcx-bar i{display:block;height:100%;width:30%;border-radius:3px;background:linear-gradient(90deg,var(--teal),var(--gold));transition:width .1s;}

/* ===== テーブル骨格 ===== */
.pcx table.pcx-t{border-collapse:separate!important;border-spacing:0!important;table-layout:fixed!important;width:1346px!important;min-width:1346px!important;max-width:none!important;margin:0!important;background:#fff;font-size:10.5px;line-height:1.38;border:none!important;}
.pcx col.c-head{width:108px;}.pcx col.c-feat{width:126px;}.pcx col.c-nocut{width:128px;}.pcx col.c-cut{width:136px;}.pcx col.c-loan{width:120px;}.pcx col.c-cases{width:104px;}.pcx col.c-method{width:112px;}.pcx col.c-menu{width:128px;}.pcx col.c-anes{width:118px;}.pcx col.c-access{width:142px;}.pcx col.c-action{width:124px;}
.pcx table.pcx-t th,.pcx table.pcx-t td{text-align:center!important;vertical-align:middle!important;white-space:normal!important;padding:7px 6px;border:none!important;border-right:1px solid var(--line)!important;border-bottom:1px solid var(--line)!important;}
.pcx table.pcx-t thead th,.pcx table.pcx-t th.px-rh{position:relative;overflow:hidden;}
.pcx table.pcx-t tr>*:last-child{border-right:none!important;}
.pcx table.pcx-t tbody tr:last-child>*{border-bottom:none!important;}

/* ヘッダー：カテゴリ行（ネイビー帯＋ゴールド罫） */
.pcx table.pcx-t thead tr.px-grp th{background:var(--ink)!important;color:#fff!important;font-size:9px;font-weight:600;letter-spacing:.18em;padding:3px 2px;line-height:1.3;border-right:1px solid rgba(255,255,255,.12)!important;border-bottom:1px solid rgba(255,255,255,.08)!important;}
.pcx table.pcx-t thead tr.px-grp th span{display:inline-flex;align-items:center;gap:5px;padding:0 6px;}
.pcx table.pcx-t thead tr.px-grp th span::before,.pcx table.pcx-t thead tr.px-grp th span::after{content:"";width:10px;height:1px;background:var(--gold);}
/* ヘッダー：項目行（生成り地＋ネイビー文字） */
.pcx table.pcx-t thead tr.px-itm th{background:var(--sand)!important;color:var(--ink)!important;font-size:11px;font-weight:800;line-height:1.2;padding:5px 3px 6px;letter-spacing:.04em;border-right:1px solid var(--line)!important;border-bottom:2px solid var(--ink)!important;}
.pcx table.pcx-t thead th svg{display:inline-block;vertical-align:-2px;width:13px;height:13px;margin-right:3px;fill:none;stroke:var(--teal);stroke-width:2;stroke-linecap:round;stroke-linejoin:round;}
.pcx table.pcx-t thead th .q{display:block;margin-top:2px;font-size:8.5px;font-weight:600;color:var(--teal);letter-spacing:0;}
.pcx table.pcx-t thead th .q::before{content:"Q.";margin-right:2px;font-family:"Helvetica Neue",Arial,sans-serif;font-weight:700;color:var(--gold);}
.pcx table.pcx-t thead th.px-th-cv{background:var(--cream2)!important;color:var(--ink)!important;border-bottom-color:var(--gold)!important;}
.pcx table.pcx-t thead th.px-th-cv .q{color:var(--cv3);}
.pcx table.pcx-t thead th.px-th-cv .q::before{content:none;}
.pcx table.pcx-t thead th.flash{animation:pcx-flash 1s ease;}
@keyframes pcx-flash{0%,100%{background:var(--sand)}30%{background:var(--gold2)}}

/* 列ゼブラ */
.pcx tr.px-other td:nth-child(odd){background:var(--zebra)!important;}
.pcx tr.px-other td:nth-child(even){background:#fff!important;}

/* 固定列 */
.pcx table.pcx-t .px-stk{position:sticky!important;left:0;z-index:3;box-shadow:5px 0 10px -4px rgba(110,30,33,.16);}
.pcx table.pcx-t thead th.px-stk{z-index:5;background:var(--ink2)!important;color:#fff!important;font-size:10.5px;letter-spacing:.1em;}
.pcx table.pcx-t th.px-rh{background:#fff!important;padding:7px 6px;border-right:1px solid var(--line)!important;}
.pcx .rh-ban{display:block;margin:0 auto;}
.pcx .rh-ban img{display:block;width:auto;max-width:100%;max-height:42px;height:auto;margin:0 auto;border-radius:6px;border:1px solid var(--line);background:#fff;}
.pcx .rh-name{display:flex;align-items:center;justify-content:center;gap:4px;margin:4px auto 5px;font-size:10.5px;font-weight:800;color:var(--ink);line-height:1.22;}
.pcx .rh-name i{flex:none;width:6px;height:6px;border-radius:50%;box-shadow:0 0 0 2px rgba(110,30,33,.07);}
.pcx .rh-btn{display:block;padding:5px 2px;border-radius:999px;font-size:9px;font-weight:700;line-height:1.25;text-decoration:none!important;background:#fff;color:var(--ink)!important;border:1px solid var(--ink);transition:.15s;}
.pcx .rh-btn:hover{background:var(--ink);color:#fff!important;}

/* イチオシ行（シャンパンゴールド） */
.pcx tr.px-best>*{background:var(--cream)!important;border-top:1.5px solid var(--gold)!important;border-bottom:1.5px solid var(--gold)!important;}
.pcx tr.px-best td:nth-child(odd){background:#faf3e7!important;}
.pcx tr.px-best th.px-rh{background:linear-gradient(180deg,#f7ecd8,#fdf9f2 60%)!important;border-left:4px solid var(--gold)!important;padding-top:19px;}
.pcx .rh-ribbon{position:absolute;top:0;left:0;right:0;display:block;padding:3px 0;background:linear-gradient(90deg,#a07c45,#c9a46b,#a07c45);color:#fff;font-size:8.5px;font-weight:800;letter-spacing:.1em;line-height:1.2;}
.pcx .rh-ribbon::before{content:"♛ ";}
.pcx tr.px-best .rh-ban img{border:1.5px solid var(--gold);}

/* CTA（汎用ゴールド） */
.pcx .btn-gold{position:relative;overflow:hidden;display:block;padding:7px 2px;border-radius:999px;background:linear-gradient(180deg,#d9b980,#b48f57);color:#fff!important;font-size:9px;font-weight:800;line-height:1.25;text-decoration:none!important;box-shadow:0 3px 0 #8a6a3a,0 5px 10px rgba(138,106,58,.3);}
.pcx .btn-gold::after{content:"";position:absolute;top:0;left:-100%;width:100%;height:100%;background:linear-gradient(to right,rgba(255,255,255,0),rgba(255,255,255,.5),rgba(255,255,255,0));animation:pcx-shine 3s infinite;}
@keyframes pcx-shine{0%{left:-100%}20%{left:100%}100%{left:100%}}
.pcx .btn-gold:active{transform:translateY(2px);box-shadow:0 1px 0 #8a6a3a;}
.pcx td .btn-gold{font-size:9.5px;}

/* ===== 項目内トップ評価 ===== */
.pcx .px-win{position:absolute;top:0;right:0;display:inline-flex;align-items:center;gap:1px;padding:1px 5px 1px 4px;border-radius:0 0 0 6px;background:var(--teal);color:#fff;font-size:8px;font-weight:800;line-height:1.4;letter-spacing:.04em;}
.pcx .px-win::before{content:"";width:9px;height:9px;background:currentColor;clip-path:polygon(0 30%,25% 55%,50% 10%,75% 55%,100% 30%,88% 90%,12% 90%);margin-right:2px;}
.pcx tr.px-best .px-win{background:var(--gold);color:#fff;}

/* ===== 特徴 ===== */
.pcx .px-fit{display:block;margin-bottom:4px;font-size:9px;font-weight:700;color:var(--steel);line-height:1.3;white-space:nowrap;}
.pcx tr.px-best .px-fit{color:var(--gold-dk);}
.pcx .px-tag{display:block;margin:0 auto 3px;padding:3px 5px;border-radius:5px;font-size:9px;font-weight:700;line-height:1.3;text-align:left;white-space:nowrap;background:#fff;border:1px solid var(--line);color:var(--text);}
.pcx .px-tag:last-child{margin-bottom:0;}
.pcx .px-tag::before{content:"✓";display:inline-block;margin-right:3px;color:var(--teal);font-weight:900;}
.pcx tr.px-best .px-tag{border-color:#dcc8a4;}
.pcx tr.px-best .px-tag::before{color:var(--teal);}
.pcx tr.px-best .px-tag.px-tag-em{background:var(--teal);border-color:var(--teal);color:#fff;}
.pcx tr.px-best .px-tag.px-tag-em::before{color:#fff;}

/* ===== 評価マーク ===== */
.pcx .px-ev{display:inline-flex;align-items:center;justify-content:center;gap:4px;font-size:11px;font-weight:700;color:var(--steel);line-height:1.25;}
.pcx .px-mk{flex:none;display:inline-flex;align-items:center;justify-content:center;width:18px;height:18px;border-radius:50%;font-size:11px;font-weight:900;line-height:1;background:#ece9e3;color:#7a8288;}
.pcx .px-mk-s{background:var(--teal);color:#fff;box-shadow:0 0 0 1.5px #fff,0 0 0 2.5px var(--teal);}
.pcx .px-mk-x{background:#f6e9e5;color:#c07a6b;}
.pcx tr.px-best .px-ev{color:var(--ink);font-size:11.5px;}
.pcx .px-n{display:block;margin-top:3px;font-size:8.5px;line-height:1.38;color:var(--muted);font-weight:500;}
.pcx sup{font-size:7px;color:var(--gold);vertical-align:super;margin-left:1px;}

/* ===== 費用 ===== */
.pcx .px-plan{display:inline-block;margin-bottom:3px;padding:1px 6px;border-radius:3px;background:#f0ede7;color:var(--steel);font-size:8.5px;font-weight:700;line-height:1.4;white-space:nowrap;}
.pcx tr.px-best .px-plan{background:var(--ink);color:#fff;}
.pcx .px-pr{display:block;font-family:"Helvetica Neue",Arial,"Hiragino Kaku Gothic ProN",sans-serif;font-weight:800;line-height:1.05;color:var(--ink);font-feature-settings:"palt";}
.pcx .px-pr b{font-size:18px;letter-spacing:-.01em;}
.pcx .px-pr em{font-style:normal;font-size:9px;margin-left:1px;}
.pcx tr.px-best .px-pr{color:var(--red);}
.pcx tr.px-best .px-pr b{font-size:23px;background:linear-gradient(transparent 70%,rgba(180,143,87,.3) 70%);padding:0 1px;}

/* ===== 医療ローン ===== */
.pcx .px-ok{display:inline-block;margin-bottom:3px;padding:1px 7px;border-radius:999px;background:var(--teal);color:#fff;font-size:8.5px;font-weight:800;line-height:1.4;}
.pcx .px-loan{display:block;font-size:9px;font-weight:700;color:var(--ink);line-height:1.1;}
.pcx .px-loan b{font-family:"Helvetica Neue",Arial,sans-serif;font-size:21px;color:var(--red);font-weight:800;letter-spacing:-.01em;}
.pcx .px-loan small{font-size:9px;color:var(--red);}
.pcx .px-off{display:block;font-size:9.5px;font-weight:700;color:var(--off);line-height:1.4;}
.pcx .px-off::before{content:"—";display:block;font-size:14px;color:#cfcac1;line-height:1;margin-bottom:2px;}

/* ===== 数値＋メーター ===== */
.pcx .px-cap{display:block;font-size:8.5px;font-weight:600;color:var(--muted);letter-spacing:.08em;margin-bottom:2px;}
.pcx .px-big{display:block;font-size:16px;font-weight:800;color:var(--ink);line-height:1.1;}
.pcx .px-big small{font-size:9px;}
.pcx tr.px-best .px-big{font-size:19px;color:var(--red);}
.pcx .px-meter{display:flex;gap:2px;justify-content:center;margin:4px auto 0;}
.pcx .px-meter i{display:block;width:9px;height:4px;border-radius:2px;background:#e4dfd6;}
.pcx .px-meter i.f{background:var(--teal);}
.pcx tr.px-best .px-meter i.f{background:var(--gold);}

/* ===== ピル ===== */
.pcx .px-cnt{display:block;margin-bottom:4px;font-size:9px;font-weight:700;color:var(--muted);}
.pcx .px-cnt b{font-family:"Helvetica Neue",Arial,sans-serif;font-size:16px;color:var(--teal);margin-right:1px;}
.pcx tr.px-best .px-cnt b{font-size:19px;color:var(--red);}
.pcx .px-pills{display:flex;flex-wrap:wrap;justify-content:center;gap:3px;margin:0!important;padding:0!important;list-style:none!important;}
.pcx .px-pills li{margin:0!important;padding:1px 6px!important;border-radius:999px;background:var(--sand);border:1px solid var(--line);color:var(--steel);font-size:8.5px;font-weight:600;line-height:1.45;white-space:nowrap;list-style:none!important;}
.pcx .px-pills li::before,.pcx .px-pills li::marker{content:none!important;display:none!important;}
.pcx tr.px-best .px-pills li{background:#fff;border-color:#dcc8a4;color:var(--ink);}
.pcx .px-more{display:inline-block;margin-top:5px;padding:2px 7px;border-radius:999px;border:1px solid var(--teal-b);background:var(--teal-l);color:var(--teal);font-size:8.5px;font-weight:700;line-height:1.4;cursor:pointer;white-space:nowrap;transition:.15s;}
.pcx .px-more::after{content:" ＋";color:var(--teal);}
.pcx .px-more:hover{background:var(--teal);color:#fff;}
.pcx .px-more:hover::after{color:#fff;}
.pcx tr.px-best .px-more{background:var(--teal);border-color:var(--teal);color:#fff;}
.pcx tr.px-best .px-more::after{color:var(--gold2);}

/* ===== 詳細列 ===== */
.pcx .px-mc{display:block;margin-bottom:5px;font-size:8.5px;font-weight:700;color:var(--cv3);line-height:1.3;white-space:nowrap;}
.pcx .btn-off{display:block;padding:7px 2px;border-radius:999px;background:var(--ink);color:#fff!important;font-size:9.5px;font-weight:700;line-height:1.25;text-decoration:none!important;box-shadow:0 2px 0 var(--ink2);transition:.15s;}
.pcx .btn-off:hover{background:var(--steel);}
.pcx .btn-dt{display:block;margin-top:6px;font-size:8.5px;font-weight:700;color:var(--teal)!important;text-decoration:underline!important;text-underline-offset:2px;}
.pcx .btn-dt::after{content:" ›";}

/* ===== 凡例・注釈 ===== */
.pcx .pcx-legend{display:flex;flex-wrap:wrap;align-items:center;gap:4px 10px;margin:7px 2px 0;font-size:9.5px;color:var(--muted);font-weight:700;}
.pcx .pcx-legend .px-mk{width:14px;height:14px;font-size:9px;margin-right:2px;}
.pcx .pcx-legend .px-win{position:static;border-radius:3px;margin-right:2px;}
.pcx .pcx-note{margin:8px 2px 0!important;padding:8px 10px!important;border-radius:8px;background:var(--sand);font-size:9.5px;line-height:1.6;color:var(--muted);}

/* ===== モーダル ===== */
.pcx .pcx-tg{position:fixed;top:0;left:0;width:1px;height:1px;margin:0;opacity:0;pointer-events:none;}
.pcx .pcx-modal{display:none;position:fixed;inset:0;z-index:99999;align-items:center;justify-content:center;padding:16px;}
.pcx div:has(.pcx-tg:checked)+.pcx-modal{display:flex;}
.pcx .pcx-modal-bg{position:absolute;inset:0;background:rgba(45,18,20,.6);backdrop-filter:blur(3px);-webkit-backdrop-filter:blur(3px);cursor:pointer;}
.pcx .pcx-modal-box{position:relative;z-index:1;width:100%;max-width:440px;max-height:82vh;display:flex;flex-direction:column;background:#fff;border-radius:16px;overflow:hidden;box-shadow:0 24px 60px -16px rgba(0,0,0,.45);animation:pcx-pop .25s ease;}
@keyframes pcx-pop{from{opacity:0;transform:translateY(10px) scale(.98)}to{opacity:1;transform:none}}
.pcx .pcx-modal-head{position:relative;background:var(--ink);color:#fff;font-weight:800;font-size:14px;padding:13px 16px 13px 28px;}
.pcx .pcx-modal-head::before{content:"";position:absolute;left:15px;top:50%;width:4px;height:16px;margin-top:-8px;border-radius:2px;background:var(--gold);}
.pcx .pcx-modal-body{padding:6px 16px;overflow:auto;-webkit-overflow-scrolling:touch;}
.pcx .pcx-item{text-align:left;padding:10px 2px;border-bottom:1px solid var(--line);font-size:12.5px;line-height:1.6;color:var(--text);}
.pcx .pcx-item:last-child{border-bottom:none;}
.pcx .pcx-item b{display:block;color:var(--teal);font-size:13px;margin-bottom:2px;}
.pcx .pcx-modal-foot{padding:10px;text-align:center;border-top:1px solid var(--line);background:var(--sand);}
.pcx .pcx-close{display:inline-block;cursor:pointer;background:#fff;color:var(--ink);border:1px solid var(--ink);font-weight:700;border-radius:999px;padding:8px 28px;font-size:13px;transition:.15s;}
.pcx .pcx-close:hover{background:var(--ink);color:#fff;}

/* ===== PC表示 ===== */
@media (min-width:768px){
  .pcx .pcx-ttl{font-size:16px;}
  .pcx .pcx-ttl small{font-size:10.5px;}
  .pcx .pcx-hint{font-size:10.5px;}
  .pcx .pcx-nav button{font-size:11.5px;padding:6px 12px;}
  .pcx table.pcx-t{width:1658px!important;min-width:1658px!important;font-size:12px;}
  .pcx col.c-head{width:150px;}.pcx col.c-feat{width:176px;}.pcx col.c-nocut{width:156px;}.pcx col.c-cut{width:166px;}.pcx col.c-loan{width:148px;}.pcx col.c-cases{width:124px;}.pcx col.c-method{width:132px;}.pcx col.c-menu{width:156px;}.pcx col.c-anes{width:140px;}.pcx col.c-access{width:150px;}.pcx col.c-action{width:160px;}
  .pcx table.pcx-t th,.pcx table.pcx-t td{padding:10px 8px;}
  .pcx table.pcx-t thead tr.px-grp th{font-size:10.5px;padding:4px 2px;}
  .pcx table.pcx-t thead tr.px-itm th{font-size:13px;padding:7px 4px 8px;}
  .pcx table.pcx-t thead th svg{width:16px;height:16px;}
  .pcx table.pcx-t thead th .q{font-size:10px;}
  .pcx .rh-ban img{max-height:60px;}
  .pcx .rh-name{font-size:13px;}
  .pcx .rh-ribbon{font-size:10.5px;}
  .pcx tr.px-best th.px-rh{padding-top:24px;}
  .pcx .btn-gold,.pcx td .btn-gold,.pcx .btn-off,.pcx .rh-btn{font-size:11px;padding:9px 2px;}
  .pcx .px-win{font-size:9.5px;padding:2px 7px 2px 5px;}
  .pcx .px-fit{font-size:10.5px;}
  .pcx .px-tag{font-size:10.5px;padding:4px 6px;}
  .pcx .px-ev{font-size:12.5px;}
  .pcx tr.px-best .px-ev{font-size:13.5px;}
  .pcx .px-mk{width:21px;height:21px;font-size:12px;}
  .pcx .px-n,.pcx .px-cap,.pcx .px-cnt,.pcx .px-mc{font-size:10px;}
  .pcx .px-plan,.pcx .px-ok{font-size:10px;}
  .pcx .px-pr b{font-size:21px;}
  .pcx tr.px-best .px-pr b{font-size:28px;}
  .pcx .px-loan b{font-size:25px;}
  .pcx .px-big{font-size:18px;}
  .pcx tr.px-best .px-big{font-size:23px;}
  .pcx .px-meter i{width:12px;height:5px;}
  .pcx .px-cnt b{font-size:18px;}
  .pcx tr.px-best .px-cnt b{font-size:22px;}
  .pcx .px-pills li{font-size:10px;padding:2px 7px!important;}
  .pcx .px-more,.pcx .btn-dt{font-size:10px;}
  .pcx .pcx-note,.pcx .pcx-legend{font-size:11px;}
}

/* ===== v4: スナップ・矢印・列フォーカス・ドットメーター・選び方ガイド ===== */
.pcx table.pcx-t thead tr.px-itm th{cursor:pointer;}
.pcx .pcx-ctrl{display:none;align-items:center;gap:8px;margin:6px 2px 0;}
.pcx.pcx-js .pcx-ctrl{display:flex;}
.pcx .pcx-ctrl .pcx-bar{flex:1;margin:0;}
.pcx .pcx-arw{flex:none;display:inline-flex;align-items:center;justify-content:center;width:34px;height:34px;padding:0;margin:0;border:1px solid var(--line);border-radius:50%;background:#fff;box-shadow:0 2px 6px rgba(110,30,33,.12);cursor:pointer;transition:opacity .25s,transform .15s,background .15s;}
.pcx .pcx-arw svg{display:block;width:16px;height:16px;fill:none;stroke:var(--ink);stroke-width:2.6;stroke-linecap:round;stroke-linejoin:round;}
.pcx .pcx-arw:hover{background:var(--ink);border-color:var(--ink);}
.pcx .pcx-arw:hover svg{stroke:#fff;}
.pcx .pcx-arw:active{transform:scale(.92);}
.pcx .pcx-arw.prev svg{transform:scaleX(-1);}
.pcx.is-start .pcx-arw.prev,.pcx.is-end .pcx-arw.next{opacity:.3;pointer-events:none;}
.pcx .pcx-pos{flex:none;align-self:center;margin-left:auto;padding-left:6px;font-family:"Helvetica Neue",Arial,sans-serif;font-size:9px;font-weight:700;color:var(--muted);font-feature-settings:"tnum";}
/* 列フォーカス（見出しタップ／項目ジャンプで該当列を枠で強調） */
.pcx table.pcx-t .colfocus{box-shadow:inset 2px 0 0 var(--teal),inset -2px 0 0 var(--teal)!important;}
.pcx table.pcx-t thead .colfocus{box-shadow:inset 0 3px 0 var(--gold),inset 2px 0 0 var(--teal),inset -2px 0 0 var(--teal)!important;background:var(--teal-l)!important;}
.pcx table.pcx-t tbody tr:last-child .colfocus{box-shadow:inset 2px 0 0 var(--teal),inset -2px 0 0 var(--teal),inset 0 -2px 0 var(--teal)!important;}
/* ドットメーター */
.pcx .px-cnt{display:flex;align-items:baseline;justify-content:center;gap:3px;flex-wrap:wrap;}
.pcx .px-dots{display:inline-flex;gap:2px;align-self:center;}
.pcx .px-dots i{display:block;width:5px;height:5px;border-radius:50%;background:#e4dfd6;}
.pcx .px-dots i.f{background:var(--teal);}
.pcx tr.px-best .px-dots i.f{background:var(--gold);}
/* タップ領域の拡大 */
.pcx .px-more{padding:4px 10px;margin-top:6px;}
.pcx .pcx-nav button{padding:7px 10px;}
/* キーボード操作 */
.pcx a:focus-visible,.pcx button:focus-visible,.pcx label:focus-visible,.pcx th:focus-visible{outline:2px solid var(--teal);outline-offset:2px;}
/* 選び方ガイド */
.pcx .pcx-guide{margin:12px 0 0;border:1px solid var(--line);border-radius:14px;overflow:hidden;background:#fff;box-shadow:0 4px 14px rgba(110,30,33,.08);}
.pcx .pcx-guide-h{margin:0!important;padding:8px 12px!important;background:var(--ink)!important;color:#fff!important;font-size:12px;font-weight:800;line-height:1.3;border:none!important;letter-spacing:.04em;}
.pcx .pcx-guide-h small{color:var(--gold2);font-size:9.5px;letter-spacing:.2em;margin-right:6px;}
.pcx .g-row{display:grid;grid-template-columns:1fr auto;align-items:center;gap:8px;padding:9px 12px;border-top:1px solid var(--line);}
.pcx .g-row:first-of-type{border-top:none;}
.pcx .g-row.best{background:var(--cream);box-shadow:inset 3px 0 0 var(--gold);}
.pcx .g-q{font-size:11.5px;font-weight:700;color:var(--ink);line-height:1.4;}
.pcx .g-q small{display:block;font-size:9.5px;font-weight:600;color:var(--muted);margin-top:1px;}
.pcx .g-a{display:inline-flex;align-items:center;gap:4px;padding:7px 12px;border-radius:999px;font-size:10.5px;font-weight:800;line-height:1.25;text-decoration:none!important;white-space:nowrap;background:var(--ink);color:#fff!important;}
.pcx .g-a::after{content:"›";font-size:13px;}
.pcx .g-row.best .g-a{position:relative;overflow:hidden;}
.pcx .g-row.best .g-a::before{content:"";position:absolute;top:0;left:-100%;width:100%;height:100%;background:linear-gradient(to right,rgba(255,255,255,0),rgba(255,255,255,.5),rgba(255,255,255,0));animation:pcx-shine 3s infinite;}
@media (min-width:768px){
  .pcx .px-dots i{width:6px;height:6px;}
  .pcx .pcx-pos{font-size:10.5px;}
  .pcx .pcx-guide-h{font-size:14px;padding:10px 16px!important;}
  .pcx .g-row{padding:11px 16px;}
  .pcx .g-q{font-size:13px;}
  .pcx .g-q small{font-size:11px;}
  .pcx .g-a{font-size:12px;padding:9px 16px;}
}
@media (prefers-reduced-motion:reduce){
  .pcx *,.pcx *::before,.pcx *::after{animation:none!important;transition:none!important;scroll-behavior:auto!important;}
}

/* ===== v5: CV強化・改行制御 ===== */
.pcx .px-ph{display:inline-block;}
.pcx .pcx-note .px-fn{display:block;padding-left:1em;text-indent:-1em;}
/* メンズライフ専用CV：アンバーの立体ピル */
.pcx .btn-cv{position:relative;overflow:hidden;display:block;padding:8px 2px 9px;border-radius:999px;border:1px solid var(--cv3);background:linear-gradient(180deg,#f7ae62 0%,var(--cv1) 40%,var(--cv2) 100%);color:#fff!important;font-size:9.5px;font-weight:800;line-height:1.25;letter-spacing:.02em;text-decoration:none!important;text-shadow:0 1px 1px rgba(120,50,10,.4);box-shadow:inset 0 1px 0 rgba(255,255,255,.5),0 3px 0 var(--cv3),0 6px 12px rgba(180,82,26,.35);transition:transform .1s,box-shadow .1s;}
.pcx .btn-cv::before{content:"";position:absolute;left:10%;right:10%;top:2px;height:38%;border-radius:999px;background:linear-gradient(180deg,rgba(255,255,255,.45),rgba(255,255,255,0));pointer-events:none;}
.pcx .btn-cv::after{content:"";position:absolute;top:0;left:-100%;width:100%;height:100%;background:linear-gradient(to right,rgba(255,255,255,0),rgba(255,255,255,.5),rgba(255,255,255,0));animation:pcx-shine 3s infinite;}
.pcx .btn-cv:active{transform:translateY(3px);box-shadow:inset 0 1px 0 rgba(255,255,255,.5),0 0 0 var(--cv3),0 2px 4px rgba(180,82,26,.35);}
@keyframes pcx-pulse{0%,100%{transform:translateY(0)}50%{transform:translateY(-2px)}}
.pcx td .btn-cv{font-size:10px;}
/* 見積・相談だけでもOK（ボルドーの吹き出し） */
.pcx .px-mc{position:relative;display:inline-block!important;margin:0 auto 9px;padding:3px 8px;border-radius:999px;background:var(--ink);color:#fff;font-size:8.5px;font-weight:700;line-height:1.3;white-space:nowrap;box-shadow:0 2px 5px rgba(110,30,33,.3);}
.pcx .px-mc::after{content:"";position:absolute;left:50%;bottom:-5px;transform:translateX(-50%);border-left:5px solid transparent;border-right:5px solid transparent;border-top:6px solid var(--ink);}
/* ガイドのメンズライフボタンも同じアンバーに統一 */
.pcx .g-row.best .g-a{border:1px solid var(--cv3);background:linear-gradient(180deg,#f7ae62 0%,var(--cv1) 40%,var(--cv2) 100%);color:#fff!important;text-shadow:0 1px 1px rgba(120,50,10,.4);box-shadow:inset 0 1px 0 rgba(255,255,255,.5),0 3px 0 var(--cv3),0 5px 10px rgba(180,82,26,.3);border-radius:999px;}
@media (min-width:768px){
  .pcx .btn-cv,.pcx td .btn-cv{font-size:11.5px;padding:10px 2px 11px;}
  .pcx .px-mc{font-size:10px;padding:4px 10px;}
}
@media (max-width:360px){
  .pcx.pcx-js .pcx-hint{display:none;}
  .pcx .pcx-ttl{font-size:12.5px;}
}
.pcx th.px-rh .btn-cv{font-size:8.5px;letter-spacing:0;padding:8px 0 9px;}
.pcx .btn-cv .px-ph{white-space:nowrap;}
.pcx .btn-cv::before{opacity:.7;}
@media (min-width:768px){.pcx th.px-rh .btn-cv{font-size:11px;padding:10px 0 11px;}}
@media (prefers-reduced-motion:reduce){.pcx .btn-cv{animation:none!important;}}

/* ===== v7: 費用（切らない／切る） ===== */
.pcx td.px-pc{vertical-align:middle!important;}
.pcx .kind{display:block;width:max-content;margin:0 auto 4px;padding:1px 8px;border-radius:999px;font-size:8px;font-weight:800;line-height:1.5;letter-spacing:.06em;}
.pcx .kind-nc{background:var(--teal-l);color:var(--teal);border:1px solid var(--teal-b);}
.pcx .kind-ct{background:#fbefe7;color:var(--red);border:1px solid #efcdb9;}
.pcx td.px-pc .px-plan{display:block;width:auto;margin:0 0 3px;padding:2px 4px;white-space:normal;line-height:1.3;}
.pcx .px-was .px-sep{color:#cfcac1;margin:0 2px;}
.pcx .px-sym-l{flex-basis:100%;}
.pcx td.px-pc .px-pr{margin:2px 0 1px;}
.pcx td.px-pc .px-pr em{font-size:9px;}
.pcx .px-was{display:block;font-size:8.5px;font-weight:600;color:var(--muted);line-height:1.3;}
.pcx .px-sym{display:flex;flex-wrap:wrap;justify-content:center;gap:2px 3px;margin-top:4px;padding-top:4px;border-top:1px dashed var(--line);}
.pcx .px-sym-l{flex-basis:100%;font-size:7.5px;font-weight:700;color:var(--muted);letter-spacing:.1em;line-height:1.2;}
.pcx .px-sym i{font-style:normal;padding:1px 6px;border-radius:999px;background:var(--teal-l);border:1px solid var(--teal-b);color:var(--teal);font-size:8px;font-weight:700;line-height:1.45;white-space:nowrap;}
.pcx tr.px-best .px-sym i{background:#fff;border-color:#dcc8a4;color:var(--ink);}
.pcx tr.px-best .px-sym{border-top-color:rgba(180,143,87,.45);}
.pcx td.px-pc .px-n{margin-top:3px;}
.pcx td.px-na{vertical-align:middle!important;background:repeating-linear-gradient(135deg,#faf8f4 0 6px,#f3f0e9 6px 12px)!important;}
.pcx .px-na-t{display:block;font-size:11px;font-weight:700;color:var(--off);}
.pcx .px-na-t::before{content:"—";display:block;font-size:14px;color:#cfcac1;line-height:1;margin-bottom:2px;}
@media (min-width:768px){
  .pcx .kind{font-size:9.5px;}
  .pcx .px-was{font-size:10px;}
