/* ===== v14: 横スクロールを促すUI（スマホのみ・JS有効時のみ） ===== */
.pcx .pcx-edge,.pcx .pcx-swipe{display:none;}
@media (max-width:767px){
  /* 右端の「まだ続く」シェブロン */
  .pcx.pcx-js .pcx-edge{display:flex;position:absolute;right:5px;top:50%;z-index:6;width:22px;height:22px;margin-top:-11px;border-radius:50%;background:rgba(255,255,255,.95);border:1px solid var(--line);align-items:center;justify-content:center;pointer-events:none;box-shadow:0 2px 6px rgba(110,30,33,.22);transition:opacity .3s;animation:pcx-edge 1.3s ease-in-out infinite;}
  .pcx .pcx-edge svg{width:12px;height:12px;fill:none;stroke:var(--teal);stroke-width:3;stroke-linecap:round;stroke-linejoin:round;}
  .pcx.is-end .pcx-edge{opacity:0;}
  /* 初回だけ出るスワイプ案内 */
  .pcx.pcx-js .pcx-swipe{display:flex;position:absolute;left:112px;right:4px;top:46%;z-index:7;justify-content:center;pointer-events:none;transition:opacity .4s,transform .4s;}
  .pcx .pcx-swipe-in{display:inline-flex;align-items:center;gap:7px;padding:8px 13px 8px 10px;border-radius:999px;background:rgba(110,30,33,.92);border:1px solid rgba(230,207,164,.6);box-shadow:0 8px 22px rgba(45,18,20,.35);color:#fff;backdrop-filter:blur(2px);-webkit-backdrop-filter:blur(2px);}
  .pcx .pcx-hand{flex:none;width:22px;height:22px;fill:#fff;stroke:var(--ink);stroke-width:1.2;stroke-linejoin:round;animation:pcx-hand 1.6s ease-in-out infinite;}
  .pcx .pcx-swipe-t{font-size:10px;font-weight:700;line-height:1.35;white-space:nowrap;text-align:left;}
  .pcx .pcx-swipe-t b{color:var(--gold2);font-weight:800;}
  .pcx .pcx-chev{flex:none;width:16px;height:16px;fill:none;stroke:var(--gold2);stroke-width:2.6;stroke-linecap:round;stroke-linejoin:round;animation:pcx-edge 1.3s ease-in-out infinite;}
  .pcx.is-scrolled .pcx-swipe,.pcx.hint-done .pcx-swipe{opacity:0;transform:translateY(6px);}
}
@keyframes pcx-hand{0%{transform:translateX(6px) rotate(0)}45%{transform:translateX(-8px) rotate(-12deg)}60%{transform:translateX(-8px) rotate(-12deg)}100%{transform:translateX(6px) rotate(0)}}
@keyframes pcx-edge{0%,100%{transform:translateX(0)}50%{transform:translateX(3px)}}
@media (prefers-reduced-motion:reduce){.pcx .pcx-hand,.pcx .pcx-chev,.pcx.pcx-js .pcx-edge{animation:none!important;}}


/* ===== v16: 調整（グループ行・リボン非表示／矢印アイコン／バナー拡大／特徴の中央揃え） ===== */
/* 「OVERVIEW」等のグループ行を非表示（rowspanの「クリニック」セルは残すため高さ0で畳む） */
.pcx table.pcx-t thead tr.px-grp th:not(.px-stk){padding:0!important;height:0!important;font-size:0!important;line-height:0!important;border:none!important;background:transparent!important;}
