  /* ベーススタイル */
  #hokei-diagnosis-tool {
    font-family: "Helvetica Neue", Arial, "Hiragino Kaku Gothic ProN", "Hiragino Sans", Meiryo, sans-serif;
    max-width: 600px;
    margin: 0 auto;
    background: #ffffff;
    border: 1px solid #e0e0e0;
    border-radius: 12px;
    box-shadow: 0 4px 20px rgba(0,0,0,0.08);
    overflow: hidden;
    color: #333;
  }

  /* ヘッダー・進行状況 */
  .dt-header {
    background: #f9f9f9;
    padding: 15px;
    text-align: center;
    border-bottom: 1px solid #eee;
  }
  .dt-progress-bar {
    height: 8px;
    background: #eee;
    border-radius: 4px;
    margin-top: 8px;
    overflow: hidden;
    width: 80%;
    margin-left: auto;
    margin-right: auto;
  }
  .dt-progress-fill {
    height: 100%;
    background: linear-gradient(90deg, #2cb696, #26a69a);
    width: 0%;
    transition: width 0.4s ease;
  }

  /* コンテンツエリア */
  .dt-content {
    padding: 25px 20px;
    min-height: 350px;
    display: flex;
    flex-direction: column;
    justify-content: center;
  }

  /* スタート画面専用スタイル */
  #dt-screen-start {
    padding: 0 !important;
    min-height: auto;
    background: transparent;
    cursor: pointer;
  }

  /* スタート画像（バナー） */
  .dt-start-img {
    width: 100%;
    height: auto;
    display: block;
    transition: opacity 0.2s;
  }
  .dt-start-img:hover {
    opacity: 0.9;
  }

  /* 質問・選択肢 */
  .dt-question-text {
    font-size: 1.2rem;
    font-weight: bold;
    margin-bottom: 25px;
    text-align: center;
    line-height: 1.4;
  }
  .dt-options {
    display: flex;
    flex-direction: column;
    gap: 12px;
  }
  .dt-btn {
    padding: 16px;
    background: #fff;
    border: 2px solid #e0e0e0;
    border-radius: 8px;
    cursor: pointer;
    text-align: left;
    font-size: 1rem;
    font-weight: 500;
    transition: all 0.2s;
    color: #444;
    width: 100%;
    position: relative;
  }
  .dt-btn:hover {
    border-color: #2cb696;
    background: #f0fcf9;
    color: #2cb696;
    transform: translateY(-2px);
    box-shadow: 0 4px 8px rgba(0,0,0,0.05);
  }
  .dt-btn:active {
    transform: translateY(0);
  }

  /* 戻るボタン */
  .dt-back-btn {
    margin-top: 20px;
    background: none;
    border: none;
    color: #999;
    cursor: pointer;
    text-decoration: underline;
    font-size: 0.85rem;
    display: block;
    margin-left: auto;
    margin-right: auto;
    padding: 10px;
  }

  /* 結果画面デザイン */
  .dt-result-box {
    text-align: center;
    animation: fadeIn 0.6s ease;
  }

  /* 結果ヘッダー */
  .dt-result-header {
    font-size: 0.9rem;
    color: #666;
    margin-bottom: 5px;
    font-weight: bold;
  }

  /* 診断結果タイプ（軽度・中度・重度） */
  .dt-result-type-box {
    display: inline-block;
    padding: 10px 30px;
    margin-bottom: 20px;
    border-bottom: 2px solid #2cb696;
  }
  .dt-result-type {
    font-size: 2rem;
    font-weight: bold;
    color: #2cb696;
    letter-spacing: 2px;
  }

