    font-size: 0.9rem;
    font-weight: bold;
    color: #e74c3c;
    margin-bottom: 5px;
    display: block;
  }
  .dt-price-value-wrap {
    font-size: 1.2rem;
    font-weight: bold;
    color: #333;
    display: flex;
    align-items: baseline;
    justify-content: center;
    gap: 4px;
  }
