    font-size: 2.8rem;
    color: #e74c3c;
    font-family: "Arial", sans-serif;
    line-height: 1;
  }
  .dt-price-unit {
    font-size: 1.2rem;
    color: #333;
  }

  /* 解説テキスト */
  .dt-result-desc {
    font-size: 0.95rem;
    text-align: left;
    background: #f9f9f9;
    padding: 15px 20px;
    border-radius: 8px;
    margin-bottom: 25px;
    line-height: 1.7;
    color: #444;
  }

  /* CTAボタン */
  .dt-cta-btn {
    display: block;
    width: 100%;
    padding: 18px;
    padding-right: 40px; /* 矢印のスペース確保 */
    background: linear-gradient(135deg, #e74c3c, #c0392b);
    color: #fff;
    text-align: center;
    text-decoration: none;
    font-weight: bold;
    font-size: 1.2rem;
