    align-items: center;
    justify-content: center;
    gap: 8px;
    border: 1px solid #c8e6c9;
  }

  .dt-note {
    font-size: 0.75rem;
    color: #999;
    margin-top: 10px;
    text-align: left;
    line-height: 1.5;
  }

  /* 都道府県グリッド */
  .pref-grid {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 10px;
  }
  .pref-grid .dt-btn {
    padding: 12px;
    font-size: 0.9rem;
    text-align: center;
  }

